def days_to_expiry(self) -> int:
    """Calculate calendar days until expiration (not time-based)."""
    if not self.expiry:
        return 0
    try:
        expiry_date = datetime.strptime(self.expiry, "%Y-%m-%d").date()
        today = datetime.now().date()
        return max(0, (expiry_date - today).days)
    except ValueError:
        return 0
